//! 🔐️ Kernel issues an exact member read from the real envelope and registry capability.
use crate::os_store::{ErasedSnapshotRead,OwnerRef,SpaceMember,CHILD_RESTORE_MAXIMUM_FIELD_BYTES};
use crate::os_io::ArtifactRef;
use semio_framework_value::{NativeDecodeControl,ValueError,ValueRefusalKind};
pub struct CapturedMemberSnapshotRead{
 owner:OwnerRef,reference:ArtifactRef,revision:[u8;32],snapshot:ErasedSnapshotRead,
}
impl CapturedMemberSnapshotRead{
 pub fn owner(&self)->&OwnerRef{&self.owner}
 pub fn reference(&self)->&ArtifactRef{&self.reference}
 pub fn revision(&self)->&[u8;32]{&self.revision}
 pub fn get<S:Send+Sync+'static>(&self)->Option<&S>{self.snapshot.get::<S>()}
 pub fn into_parts(self)->(OwnerRef,ArtifactRef,[u8;32],ErasedSnapshotRead){(self.owner,self.reference,self.revision,self.snapshot)}
}
fn invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn copy_reference(value:&ArtifactRef,control:&mut NativeDecodeControl<'_>)->Result<ArtifactRef,ValueError>{
 Ok(ArtifactRef{artifact_id:control.copy_text(&value.artifact_id)?,dialect:crate::os_io::ArtifactDialect{artifact_kind:control.copy_text(&value.dialect.artifact_kind)?,standard:control.copy_text(&value.dialect.standard)?,subset:control.copy_text(&value.dialect.subset)?}})
}
pub fn capture_member_snapshot_read<M:SpaceMember+?Sized>(
 member:&M,owner:&OwnerRef,target:&ArtifactRef,control:&mut NativeDecodeControl<'_>,
)->Result<CapturedMemberSnapshotRead,ValueError>{
 control.scoped_stage(|control|{
  control.begin_stage(14)?;
  let identity=member.member_snapshot_identity().ok_or_else(||invalid("child member has no declared envelope dialect"))?;
  if identity.artifact_id!=target.artifact_id||identity.dialect!=&target.dialect{return Err(invalid("child member differs from the admitted full addressed target"))}
  if identity.owner.is_some_and(|actual|actual!=owner){return Err(invalid("child member differs from the admitted logical owner tuple"))}
  for value in [&owner.slot,&owner.child_id,&owner.parent.artifact_id,&owner.parent.dialect.artifact_kind,&owner.parent.dialect.standard,&owner.parent.dialect.subset,&target.artifact_id,&target.dialect.artifact_kind,&target.dialect.standard,&target.dialect.subset]{
   control.step()?;if value.len()>CHILD_RESTORE_MAXIMUM_FIELD_BYTES{return Err(invalid("captured member identity exceeds its declared metadata bound"))}
  }
  let(generation,revision)=member.one_item_publication_identity();
  let snapshot=member.snapshot_read_erased_now()?;
  if snapshot.lease.as_ref().is_none_or(|lease|!lease.registry.authority_matches(generation,revision)){return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"child member publication changed during synchronous read capture"))}
  let slot=control.copy_text(&owner.slot)?;control.step()?;
  let child_id=control.copy_text(&owner.child_id)?;control.step()?;
  let parent=copy_reference(&owner.parent,control)?;control.step()?;
  let reference=copy_reference(target,control)?;control.step()?;
  control.checkpoint()?;
  Ok(CapturedMemberSnapshotRead{owner:OwnerRef{parent,slot,child_id},reference,revision,snapshot})
 })
}
